mapper.select:
        
        where 1=1
		
			AND id = #{id,jdbcType=VARCHAR}
		
        
			AND parent_id = #{parentId}
		
		
			AND group_name like concat('%', #{groupName}, '%')
		
		
		order by  d.show_order

        
        SELECT ID,PARENT_ID,GROUP_NAME,CODE,ROWNUM  AS SHOW_ORDER,"LEVEL",TABLE_NAME,TABLE_ID FROM (
			SELECT UNITID AS ID ,'1' AS PARENT_ID ,unitfullname AS GROUP_NAME,QZH  AS CODE ,'1' AS "LEVEL",'UNITID' AS TABLE_NAME,UNITID AS TABLE_ID FROM T_ALLUNIT ORDER BY QZH
		)t
